CREATE OR REPLACE FUNCTION public.account_access_state(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.subscriptions%rowtype; v_state text; v_grace_ends timestamptz; v_now timestamptz := public.billing_now(p_account);
begin
 select * into s from public.subscriptions x where x.account_id = p_account
  order by (x.status is distinct from 'canceled') desc, x.created_at desc, x.id limit 1;
 if not found then
  return jsonb_build_object('state','none','read_only',false,'origin',null,'policy_version','access-v1');
 end if;
 if s.origin = 'synthetic_seed' then
  v_state := case when s.status in ('active','trialing') then 'active'
                  when s.status = 'past_due' then 'past_due_reminder'
                  when s.status = 'canceled' then 'ended' else 'none' end;
 elsif s.status = 'canceled' then v_state := 'ended';
 elsif s.status = 'incomplete' then v_state := 'none';
 elsif s.grace_started_at is not null then
  v_grace_ends := s.grace_started_at + interval '7 days';
  v_state := case when v_now < v_grace_ends then 'grace' else 'read_only' end;
 elsif s.status = 'unpaid' then v_state := 'read_only';
 elsif s.status = 'past_due' then v_state := 'grace';
 else v_state := 'active';
 end if;
 return jsonb_build_object('state', v_state, 'read_only', v_state in ('read_only','ended'), 'origin', s.origin,
  'grace_ends_at', v_grace_ends, 'policy_version', 'access-v1',
  'cancel_scheduled', (s.status is distinct from 'canceled') and (s.cancel_at is not null or s.cancel_at_period_end));
end $function$

CREATE OR REPLACE FUNCTION public.account_add_store_refusal(p_account uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare st jsonb := public.account_access_state(p_account);
begin
 if st->>'state' in ('read_only', 'ended') then return 'account_read_only'; end if;
 if st->>'state' in ('grace', 'past_due_reminder') then return 'account_in_grace'; end if;
 if coalesce((st->>'cancel_scheduled')::boolean, false) then return 'cancellation_scheduled'; end if;
 if st->>'state' <> 'active' then return 'account_not_active'; end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.admin_audit(p_business_id uuid, p_limit integer DEFAULT 50, p_before bigint DEFAULT NULL::bigint, p_include_reads boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare acct uuid; owner_access boolean; snapshot_id bigint; result jsonb;
begin
 select b.account_id, public.is_owner_of_account(b.account_id) into acct, owner_access from public.businesses b
  where b.id = p_business_id and public.store_is_live(b.id) and (public.is_owner_of_account(b.account_id) or public.is_admin_of(b.id));
 if acct is null then raise exception 'not an administrator of business' using errcode = '42501'; end if;
 if p_limit is null or p_limit < 1 or p_limit > 100 then raise exception 'invalid limit' using errcode = '22023'; end if;
 select coalesce(max(a.id), 0) into snapshot_id from public.audit_logs a;
 select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'occurred_at', s.occurred_at, 'actor_user_id', s.actor_user_id, 'business_id', s.business_id,
   'table_name', s.table_name, 'row_id', s.row_id, 'action', s.action, 'context', s.context,
   'actor', case when s.actor_user_id is null then null else jsonb_build_object('name', ap.full_name, 'email', ap.email) end,
   'actor_kind', case when s.actor_user_id is not null then 'person' when s.actor_role = 'service_role' then 'system' else 'unknown' end,
   'detail', s.detail
     || case when s.detail ? 'user_id' then jsonb_strip_nulls(jsonb_build_object('person_name', mp.full_name, 'person_email', mp.email)) else '{}'::jsonb end
  ) order by s.id desc), '[]'::jsonb) into result
 from (
  select a.id, a.occurred_at, a.actor_user_id, a.actor_role, a.business_id, a.table_name, a.row_id, a.action, a.context,
         public.audit_detail(a.table_name, a.action, a.old_data, a.new_data) detail
  from public.audit_logs a where a.id <= snapshot_id and (p_before is null or a.id < p_before)
   and (p_include_reads or a.action <> 'read_page')
   and ((not owner_access and a.business_id = p_business_id) or (owner_access and (
    a.business_id in (select b.id from public.businesses b where b.account_id = acct and public.store_is_live(b.id))
    or (a.business_id is null and a.table_name = 'accounts' and a.row_id = acct::text)
    or (a.business_id is null and a.table_name = 'subscriptions' and (a.new_data->>'account_id' = acct::text or a.old_data->>'account_id' = acct::text)))))
  order by a.id desc limit p_limit) s
 left join public.profiles ap on ap.id = s.actor_user_id
 left join public.profiles mp on mp.id = (case when s.detail->>'user_id' ~ '^[0-9a-f-]{36}$' then (s.detail->>'user_id')::uuid end);
 insert into public.audit_logs (actor_user_id, actor_role, business_id, table_name, action, context)
 values (auth.uid(), 'authenticated', p_business_id, 'audit_logs', 'read_page', jsonb_build_object('fn', 'admin_audit', 'account_id', acct, 'snapshot_id', snapshot_id));
 return jsonb_build_object('rows', result, 'snapshot_id', snapshot_id);
end $function$

CREATE OR REPLACE FUNCTION public.admin_billing_status(p_business_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare acct uuid; result jsonb;
begin
 select b.account_id into acct from public.businesses b where b.id = p_business_id and public.store_is_live(b.id) and public.is_owner_of_account(b.account_id);
 if acct is null then raise exception 'not the owner of account' using errcode = '42501'; end if;
 select jsonb_build_object('account_id', acct, 'subscriptions', coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'status', s.status,
   'trial_end_date', s.trial_end_date, 'current_period_end', s.current_period_end, 'cancel_at_period_end', s.cancel_at_period_end,
   'cancel_at', s.cancel_at, 'origin', s.origin) order by s.created_at, s.id), '[]'::jsonb))
  into result from public.subscriptions s where s.account_id = acct;
 insert into public.audit_logs (actor_user_id, actor_role, business_id, table_name, action, context)
 values (auth.uid(), 'authenticated', p_business_id, 'subscriptions', 'read_page', jsonb_build_object('fn', 'admin_billing_status', 'account_id', acct));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.audit_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  j             jsonb;
  v_old         jsonb;
  v_new         jsonb;
  v_business_id uuid;
  v_context     jsonb;
  v_role        text;
begin
  if tg_op = 'DELETE' then
    j := to_jsonb(old);  v_old := j;              v_new := null;
  elsif tg_op = 'UPDATE' then
    j := to_jsonb(new);  v_old := to_jsonb(old);  v_new := j;
  else
    j := to_jsonb(new);  v_old := null;           v_new := j;
  end if;

  if tg_table_name = 'businesses' then
    v_business_id := (j ->> 'id')::uuid;
    v_context     := null;
  elsif j ? 'business_id' then
    v_business_id := (j ->> 'business_id')::uuid;
    v_context     := null;
  else
    v_business_id := null;                                              -- R-8
    v_context     := jsonb_strip_nulls(jsonb_build_object('id', j ->> 'id', 'account_id', j ->> 'account_id'));
  end if;

  v_role := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    current_user::text
  );

  insert into public.audit_logs
    (actor_user_id, actor_role, business_id, table_name, row_id, action, old_data, new_data, context)
  values
    (auth.uid(), v_role, v_business_id, tg_table_name, j ->> 'id', lower(tg_op), v_old, v_new, v_context);

  return null;  -- AFTER trigger: the return value is ignored
end;
$function$

CREATE OR REPLACE FUNCTION public.billing_deployment_bind(p_project_ref text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cur text;
begin
 select d.project_ref into cur from public.billing_deployment d for update;
 if cur is null then insert into public.billing_deployment (project_ref) values (p_project_ref); return 'bound'; end if;
 if cur = p_project_ref then return 'already_bound'; end if;
 raise exception 'deployment identity is immutable' using errcode = '42501';
end $function$

CREATE OR REPLACE FUNCTION public.businesses_assign_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.pharmacy_id is null then
  if exists (select 1 from public.pharmacy_identities i where i.npi = new.npi) then
   raise exception 'pharmacy identity already exists for this NPI' using errcode = '23505'; end if;
  insert into public.pharmacy_identities (id, npi) values (new.id, new.npi);
  new.pharmacy_id := new.id;
 end if;
 if new.ownership_started_at is null then new.ownership_started_at := coalesce(new.date_of_registration, now()); end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.handoff_invalidate_user(p_user uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer;
begin
  update handoff.codes set invalidated_at = now(), invalid_reason = 'logout'
   where user_id = p_user and completed_at is null and invalidated_at is null;
  get diagnostics n = row_count;
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.invitation_accept(p_invitation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.store_invitations%rowtype; v_email text := public.caller_verified_email(); v_uid uuid := auth.uid(); v_admin uuid; v_owner uuid; v_business uuid;
begin
 if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
 -- Lock order everywhere: store row first, then the invitation (avoids deadlock between concurrent acceptances).
 select x.business_id into v_business from public.store_invitations x where x.id = p_invitation;
 if v_business is null then raise exception 'invitation not found' using errcode = '42704'; end if;
 perform 1 from public.businesses b where b.id = v_business for update;
 select * into i from public.store_invitations x where x.id = p_invitation for update;
 if not found or v_email is null or i.email <> v_email then raise exception 'invitation not found' using errcode = '42704'; end if;
 if i.status <> 'pending' then return jsonb_build_object('error', 'not_pending', 'status', i.status); end if;
 if i.expires_at <= now() then update public.store_invitations x set status = 'expired' where x.id = i.id; return jsonb_build_object('error', 'expired'); end if;
 if not public.store_is_live(i.business_id) then return jsonb_build_object('error', 'store_unavailable'); end if;
 if public.account_grants_refusal(i.account_id) is not null then return jsonb_build_object('error', 'account_read_only'); end if;
 select a.owner_user_id into v_owner from public.accounts a where a.id = i.account_id;
 if i.role = 'member' then
  insert into public.user_businesses (user_id, business_id, role, is_primary) values (v_uid, i.business_id, 'member', false)
   on conflict (user_id, business_id) do nothing;
 else
  v_admin := public.current_admin_of(i.business_id);
  if v_admin is distinct from i.incumbent_admin_user_id then
   update public.store_invitations x set status = 'revoked', revoked_at = now(), status_reason = 'stale_incumbent' where x.id = i.id;
   return jsonb_build_object('error', 'stale_incumbent');
  end if;
  if v_admin <> v_uid then
   if i.former_admin_disposition = 'remove' and v_admin <> v_owner then
    delete from public.user_businesses ub where ub.business_id = i.business_id and ub.user_id = v_admin;
   else
    update public.user_businesses ub set role = 'member' where ub.business_id = i.business_id and ub.user_id = v_admin;
   end if;
  end if;
  insert into public.user_businesses (user_id, business_id, role, is_primary) values (v_uid, i.business_id, 'admin', false)
   on conflict (user_id, business_id) do update set role = 'admin';
 end if;
 if (select count(*) from public.user_businesses ub where ub.business_id = i.business_id and ub.role = 'admin') <> 1 then
  raise exception 'admin invariant violated' using errcode = '55000'; end if;
 update public.store_invitations x set status = 'accepted', accepted_at = now(), accepted_user_id = v_uid where x.id = i.id;
 -- any other pending admin invitation for this store is now stale
 update public.store_invitations x set status = 'revoked', revoked_at = now(), status_reason = 'stale_incumbent'
  where i.role = 'admin' and x.business_id = i.business_id and x.status = 'pending' and x.role = 'admin' and x.id <> i.id;
 return jsonb_build_object('status', 'accepted', 'business_id', i.business_id, 'role', i.role);
end $function$

CREATE OR REPLACE FUNCTION public.invitation_create(p_business uuid, p_email text, p_role text, p_disposition text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role text := public.store_manager_role(p_business); b public.businesses%rowtype; v_email text := lower(btrim(coalesce(p_email, '')));
        v_incumbent uuid; v_target uuid; i public.store_invitations%rowtype; v_refusal text; v_owner uuid;
begin
 if v_role is null then raise exception 'not permitted' using errcode = '42501'; end if;
 if p_role not in ('admin', 'member') then raise exception 'invalid role' using errcode = '22023'; end if;
 if p_role = 'admin' and v_role <> 'owner' then raise exception 'only the owner may appoint an admin' using errcode = '42501'; end if;
 if p_role = 'admin' and coalesce(p_disposition, '') not in ('member', 'remove') then raise exception 'former admin disposition required' using errcode = '22023'; end if;
 if p_role = 'member' and p_disposition is not null then raise exception 'disposition applies to admin invitations only' using errcode = '22023'; end if;
 if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 254 then raise exception 'invalid email' using errcode = '22023'; end if;
 select * into b from public.businesses x where x.id = p_business for update;
 v_refusal := public.account_grants_refusal(b.account_id);
 if v_refusal is not null then raise exception 'account is read-only' using errcode = '42501'; end if;
 select a.owner_user_id into v_owner from public.accounts a where a.id = b.account_id;
 select u.id into v_target from auth.users u where lower(u.email) = v_email;
 if v_target is not null then
  if v_target = v_owner and p_role = 'member' then return jsonb_build_object('error', 'owner_already_manages'); end if;
  if p_role = 'member' and exists (select 1 from public.user_businesses ub where ub.business_id = p_business and ub.user_id = v_target) then
   return jsonb_build_object('error', 'already_member'); end if;
  if p_role = 'admin' and public.current_admin_of(p_business) = v_target then return jsonb_build_object('error', 'already_admin'); end if;
 end if;
 if exists (select 1 from public.store_invitations x where x.business_id = p_business and x.status = 'pending' and x.expires_at <= now()) then
  update public.store_invitations x set status = 'expired' where x.business_id = p_business and x.status = 'pending' and x.expires_at <= now();
 end if;
 if exists (select 1 from public.store_invitations x where x.business_id = p_business and x.email = v_email and x.status = 'pending') then
  return jsonb_build_object('error', 'invitation_pending'); end if;
 if p_role = 'admin' and exists (select 1 from public.store_invitations x where x.business_id = p_business and x.role = 'admin' and x.status = 'pending') then
  return jsonb_build_object('error', 'admin_invitation_pending'); end if;
 v_incumbent := case when p_role = 'admin' then public.current_admin_of(p_business) else null end;
 if p_role = 'admin' and v_incumbent is null then raise exception 'store has no effective admin; use support recovery' using errcode = '55000'; end if;
 if p_role = 'admin' and v_incumbent = v_owner and p_disposition = 'remove' then
  raise exception 'the account owner cannot be removed from a store' using errcode = '22023', hint = 'owner_protected'; end if;
 insert into public.store_invitations (business_id, account_id, email, role, inviter_user_id, incumbent_admin_user_id, former_admin_disposition, expires_at)
  values (p_business, b.account_id, v_email, p_role, auth.uid(), v_incumbent, case when p_role = 'admin' then p_disposition end, now() + interval '7 days')
  returning * into i;
 return jsonb_build_object('invitation', jsonb_build_object('id', i.id, 'status', i.status, 'role', i.role, 'email', i.email, 'expires_at', i.expires_at, 'attempts_remaining', 5 - i.dispatch_attempts));
end $function$

CREATE OR REPLACE FUNCTION public.invitation_decline(p_invitation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_email text := public.caller_verified_email();
begin
 if auth.uid() is null or v_email is null then raise exception 'not authenticated' using errcode = '42501'; end if;
 update public.store_invitations i set status = 'declined', declined_at = now() where i.id = p_invitation and i.email = v_email and i.status = 'pending';
 if not found then raise exception 'invitation not found' using errcode = '42704'; end if;
 return jsonb_build_object('status', 'declined');
end $function$

CREATE OR REPLACE FUNCTION public.invitation_dispatch_claim(p_invitation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.store_invitations%rowtype;
begin
 select * into i from public.store_invitations x where x.id = p_invitation for update;
 if not found then return jsonb_build_object('error', 'unknown'); end if;
 if i.status <> 'pending' then return jsonb_build_object('error', 'not_pending'); end if;
 if i.expires_at <= now() then update public.store_invitations x set status = 'expired' where x.id = i.id; return jsonb_build_object('error', 'expired'); end if;
 if i.dispatch_attempts >= 5 then return jsonb_build_object('error', 'attempts_exhausted'); end if;
 if i.last_sent_at is not null and i.last_sent_at > now() - interval '60 seconds' then return jsonb_build_object('error', 'too_soon'); end if;
 update public.store_invitations x set dispatch_attempts = x.dispatch_attempts + 1, last_sent_at = now() where x.id = i.id;
 return jsonb_build_object('email', i.email, 'attempt', i.dispatch_attempts + 1, 'attempts_remaining', 4 - i.dispatch_attempts, 'expires_at', i.expires_at);
end $function$

CREATE OR REPLACE FUNCTION public.invitation_resend_check(p_invitation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.store_invitations%rowtype;
begin
 if not public.invitation_manager_ok(p_invitation) then raise exception 'not permitted' using errcode = '42501'; end if;
 select * into i from public.store_invitations x where x.id = p_invitation;
 if i.status <> 'pending' or i.expires_at <= now() then return jsonb_build_object('error', 'not_pending'); end if;
 if public.account_grants_refusal(i.account_id) is not null then raise exception 'account is read-only' using errcode = '42501'; end if;
 return jsonb_build_object('ok', true);
end $function$

CREATE OR REPLACE FUNCTION public.member_remove(p_business uuid, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role text := public.store_manager_role(p_business); r public.user_businesses%rowtype; v_owner uuid;
begin
 if v_role is null then raise exception 'not permitted' using errcode = '42501'; end if;
 perform 1 from public.businesses b where b.id = p_business for update;
 select * into r from public.user_businesses ub where ub.business_id = p_business and ub.user_id = p_user for update;
 if not found then return jsonb_build_object('removed', false); end if;
 select a.owner_user_id into v_owner from public.businesses b join public.accounts a on a.id = b.account_id where b.id = p_business;
 if p_user = v_owner then raise exception 'the account owner cannot be removed from a store' using errcode = '42501', hint = 'owner_protected'; end if;
 if r.role = 'admin' then raise exception 'the effective admin cannot be removed; replace the admin first' using errcode = '55000'; end if;
 delete from public.user_businesses ub where ub.id = r.id;
 update public.store_invitations i set status = 'revoked', revoked_at = now(), status_reason = 'member_removed'
  where i.business_id = p_business and i.status = 'pending' and i.email = (select lower(u.email) from auth.users u where u.id = p_user);
 return jsonb_build_object('removed', true);
end $function$

CREATE OR REPLACE FUNCTION public.my_invitations()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_email text := public.caller_verified_email();
begin
 if auth.uid() is null then raise exception 'not authenticated' using errcode = '42501'; end if;
 if v_email is null then return '[]'::jsonb; end if;
 return (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'store_name', b.pharmacy_name, 'role', i.role, 'expires_at', i.expires_at) order by i.created_at desc), '[]'::jsonb)
  from public.store_invitations i join public.businesses b on b.id = i.business_id
  where i.email = v_email and i.status = 'pending' and i.expires_at > now() and public.store_is_live(i.business_id));
end $function$

CREATE OR REPLACE FUNCTION public.notice_claim(p_notice uuid, p_owner text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.notification_operations%rowtype; s public.subscriptions%rowtype; v_email text; v_epoch bigint; v_grace_ends timestamptz;
begin
 select * into n from public.notification_operations x where x.id = p_notice;
 if not found or n.notice_kind is null then return jsonb_build_object('error', 'unknown'); end if;
 perform 1 from public.accounts a where a.id = n.account_id for update;
 select * into n from public.notification_operations x where x.id = p_notice for update;
 if n.status not in ('pending', 'sending') or (n.status = 'sending' and n.claim_until > now()) then return jsonb_build_object('error', 'not_claimable', 'status', n.status); end if;
 select * into s from public.subscriptions x where x.account_id = n.account_id and x.origin = 'stripe' order by (x.status is distinct from 'canceled') desc, x.created_at desc limit 1;
 if not found or s.grace_invoice_id is distinct from n.invoice_id or s.grace_started_at is null then
  update public.notification_operations x set status = 'suppressed', suppression_reason = 'recovered_or_not_in_grace', finished_at = now() where x.id = n.id;
  return jsonb_build_object('error', 'suppressed'); end if;
 if n.attempts >= 5 then
  update public.notification_operations x set status = 'attention', attention_reason = 'attempts_exhausted' where x.id = n.id;
  return jsonb_build_object('error', 'attention'); end if;
 if n.first_attempt_at is not null and now() >= n.first_attempt_at + interval '23 hours' then
  update public.notification_operations x set status = 'attention', attention_reason = 'idempotency_horizon' where x.id = n.id;
  return jsonb_build_object('error', 'attention'); end if;
 select lower(u.email) into v_email from auth.users u where u.id = n.user_id;
 if v_email is null then
  update public.notification_operations x set status = 'attention', attention_reason = 'owner_email_missing' where x.id = n.id;
  return jsonb_build_object('error', 'attention'); end if;
 v_grace_ends := s.grace_started_at + interval '7 days';
 update public.notification_operations x set status = 'sending', claim_owner = p_owner, claim_until = now() + interval '2 minutes',
   fencing_epoch = x.fencing_epoch + 1, attempts = x.attempts + 1, first_attempt_at = coalesce(x.first_attempt_at, now())
  where x.id = n.id returning x.fencing_epoch into v_epoch;
 return jsonb_build_object('id', n.id, 'epoch', v_epoch, 'kind', n.notice_kind, 'invoice_id', n.invoice_id, 'to', v_email,
   'grace_ends_at', v_grace_ends, 'amount_due_cents', n.amount_due_cents, 'attempt', n.attempts + 1, 'account_id', n.account_id);
end $function$

CREATE OR REPLACE FUNCTION public.notice_schedule_for_failure(p_stripe_subscription_id text, p_invoice text, p_grace_started timestamp with time zone, p_amount_due integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.subscriptions%rowtype; v_owner uuid;
begin
 select * into s from public.subscriptions x where x.stripe_subscription_id = p_stripe_subscription_id and x.origin = 'stripe';
 if not found then return 'unknown_subscription'; end if;
 select a.owner_user_id into v_owner from public.accounts a where a.id = s.account_id;
 insert into public.notification_operations (kind, notice_kind, dedupe_key, account_id, user_id, status, invoice_id, due_at, amount_due_cents)
  values ('renewal_payment_failed', 'renewal_payment_failed', 'renewal_payment_failed:' || p_invoice, s.account_id, v_owner, 'pending', p_invoice, p_grace_started, p_amount_due),
         ('renewal_read_only_warning', 'renewal_read_only_warning', 'renewal_read_only_warning:' || p_invoice, s.account_id, v_owner, 'pending', p_invoice, p_grace_started + interval '5 days', p_amount_due)
  on conflict do nothing;
 return 'scheduled';
end $function$

CREATE OR REPLACE FUNCTION public.notice_suppress_for_invoice(p_invoice text, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer; v_account uuid;
begin
 select x.account_id into v_account from public.notification_operations x where x.invoice_id = p_invoice limit 1;
 if v_account is null then return 0; end if;
 perform 1 from public.accounts a where a.id = v_account for update;
 update public.notification_operations x set status = 'suppressed', suppression_reason = p_reason, finished_at = now()
  where x.invoice_id = p_invoice and x.notice_kind is not null and x.status = 'pending';
 get diagnostics n = row_count;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.npi_is_valid(p_npi text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s text; i int; d int; total int := 0; dbl boolean := false;
begin
 if p_npi is null or p_npi !~ '^[0-9]{10}$' then return false; end if;
 s := '80840' || p_npi;
 for i in reverse 15..1 loop
  d := substr(s, i, 1)::int;
  if dbl then d := d * 2; if d > 9 then d := d - 9; end if; end if;
  total := total + d; dbl := not dbl;
 end loop;
 return total % 10 = 0;
end $function$

CREATE OR REPLACE FUNCTION public.npi_release_unpaid(p_operation uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not exists (select 1 from public.checkout_operations o where o.id = p_operation and o.status = 'expired_unpaid') then
  return 'not_proven_unpaid'; end if;
 update public.npi_reservations x set status = 'released'
  where x.operation_id = p_operation and x.status in ('held','checkout_bound');
 if found then return 'released'; end if;
 -- a transfer hold is never released to the public: it is detached and stays held for the exact buyer
 update public.npi_reservations x set operation_id = null, draft_id = null where x.operation_id = p_operation and x.status = 'transfer_held';
 if found then return 'released'; end if;
 return 'nothing_to_release';
end $function$

CREATE OR REPLACE FUNCTION public.npi_reserve(p_draft uuid, p_npi text)
 RETURNS TABLE(outcome text, reservation_id uuid, blocking_operation_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.npi_reservations%rowtype; v_id uuid; v_email text; t public.store_transfers%rowtype;
begin
 if not public.npi_is_valid(p_npi) then
  return query select 'invalid'::text, null::uuid, null::uuid; return; end if;
 if not exists (select 1 from public.registration_drafts d where d.id = p_draft and d.status = 'draft') then
  return query select 'draft_not_editable'::text, null::uuid, null::uuid; return; end if;
 perform pg_advisory_xact_lock(hashtextextended('apbm007a:npi:' || p_npi, 0));
 update public.npi_reservations x set status = 'released'
  where x.draft_id = p_draft and x.status = 'held' and x.npi <> p_npi;
 -- Ruling 3: the exact transfer buyer may register this NPI from the transfer's effective time until its hold expiry.
 select lower(d.owner_email) into v_email from public.registration_drafts d where d.id = p_draft;
 select x.* into t from public.store_transfers x join public.pharmacy_identities i on i.id = x.pharmacy_id
  where i.npi = p_npi and x.status = 'buyer_reserved' and x.buyer_account_id is null and x.buyer_email = v_email for update of x;
 if found then
  if now() >= t.hold_expires_at or public.billing_now(t.source_account_id) < t.effective_at then
   return query select 'unavailable'::text, null::uuid, null::uuid; return; end if;
  update public.npi_reservations x set draft_id = p_draft where x.transfer_id = t.id and x.status = 'transfer_held' returning x.id into v_id;
  if v_id is null then return query select 'unavailable'::text, null::uuid, null::uuid; return; end if;
  return query select 'held'::text, v_id, null::uuid; return;
 end if;
 if exists (select 1 from public.pharmacy_identities i where i.npi = p_npi)
    or exists (select 1 from public.businesses b where b.npi = p_npi)
    or exists (select 1 from public.npi_reservations x where x.npi = p_npi and x.status in ('op_held', 'transfer_held')) then
  return query select 'unavailable'::text, null::uuid, null::uuid; return; end if;
 select * into r from public.npi_reservations x where x.npi = p_npi and x.status in ('held','checkout_bound') for update;
 if found then
  if r.draft_id = p_draft then
   if r.status = 'held' then
    update public.npi_reservations x set expires_at = least(x.created_at + interval '2 hours', now() + interval '30 minutes') where x.id = r.id;
   end if;
   return query select r.status, r.id, r.operation_id; return;
  end if;
  if r.status = 'held' and r.expires_at <= now() then
   update public.npi_reservations x set status = 'released' where x.id = r.id;
  elsif r.status = 'checkout_bound' and r.expires_at <= now() then
   return query select 'needs_proof'::text, null::uuid, r.operation_id; return;
  else
   return query select 'unavailable'::text, null::uuid, null::uuid; return;
  end if;
 end if;
 insert into public.npi_reservations(npi, draft_id, status, expires_at)
  values (p_npi, p_draft, 'held', now() + interval '30 minutes') returning id into v_id;
 return query select 'held'::text, v_id, null::uuid;
end $function$

CREATE OR REPLACE FUNCTION public.owner_billing_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare acct uuid; s public.subscriptions%rowtype; result jsonb; v_found boolean;
begin
 select a.id into acct from public.accounts a where a.owner_user_id = auth.uid() order by a.created_at, a.id limit 1;
 if auth.uid() is null or acct is null then raise exception 'not the owner of an account' using errcode = '42501'; end if;
 select * into s from public.subscriptions x where x.account_id = acct order by (x.status is distinct from 'canceled') desc, x.created_at desc, x.id limit 1;
 v_found := found;
 result := jsonb_build_object('account_id', acct, 'access', public.account_access_state(acct),
  'subscription', case when v_found then jsonb_build_object('id', s.id, 'origin', s.origin, 'status', s.status, 'raw_status', s.raw_status,
    'quantity', s.quantity, 'current_period_start', s.current_period_start, 'current_period_end', s.current_period_end,
    'cancel_at', s.cancel_at, 'cancel_at_period_end', s.cancel_at_period_end, 'paid_through', coalesce(s.cancel_at, s.current_period_end),
    'latest_invoice_status', s.latest_invoice_status, 'grace_started_at', s.grace_started_at, 'verified_at', s.verified_at) else null end,
  'billable_count', public.account_billable_count(acct),
  'stores', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'name', b.pharmacy_name, 'npi', b.npi, 'status', b.status,
     'removal_effective_at', b.removal_effective_at) order by b.pharmacy_name, b.id), '[]'::jsonb)
   from public.businesses b where b.account_id = acct and public.store_is_live(b.id)));
 insert into public.audit_logs (actor_user_id, actor_role, business_id, table_name, action, context)
 values (auth.uid(), 'authenticated', null, 'subscriptions', 'read_page', jsonb_build_object('fn', 'owner_billing_overview', 'account_id', acct));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.owner_replace(p_account uuid, p_new_owner uuid, p_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.accounts%rowtype; v_old uuid; r record;
begin
 select * into a from public.accounts x where x.id = p_account for update;
 if not found then return jsonb_build_object('error', 'unknown_account'); end if;
 v_old := a.owner_user_id;
 if v_old = p_new_owner then return jsonb_build_object('outcome', 'already_owner'); end if;
 if not exists (select 1 from auth.users u where u.id = p_new_owner and u.email_confirmed_at is not null) then return jsonb_build_object('error', 'new_owner_not_confirmed'); end if;
 if exists (select 1 from public.accounts x where x.owner_user_id = p_new_owner) then return jsonb_build_object('error', 'new_owner_has_account'); end if;
 update public.accounts x set owner_user_id = p_new_owner where x.id = p_account;
 for r in select b.id from public.businesses b where b.account_id = p_account and b.ownership_ended_at is null loop
  perform 1 from public.businesses b where b.id = r.id for update;
  if exists (select 1 from public.user_businesses ub where ub.business_id = r.id and ub.user_id = v_old and ub.role = 'admin') then
   delete from public.user_businesses ub where ub.business_id = r.id and ub.user_id = v_old;
   insert into public.user_businesses (user_id, business_id, role, is_primary) values (p_new_owner, r.id, 'admin', false)
    on conflict (user_id, business_id) do update set role = 'admin';
  else
   delete from public.user_businesses ub where ub.business_id = r.id and ub.user_id = v_old;
  end if;
 end loop;
 update public.store_invitations i set status = 'revoked', revoked_at = now(), status_reason = 'owner_replaced'
  where i.account_id = p_account and i.status = 'pending' and i.inviter_user_id = v_old;
 if to_regprocedure('public.handoff_invalidate_user(uuid)') is not null then perform public.handoff_invalidate_user(v_old); end if;
 return jsonb_build_object('outcome', 'replaced', 'old_owner', v_old, 'new_owner', p_new_owner);
end $function$

CREATE OR REPLACE FUNCTION public.owner_store_operations()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare acct uuid;
begin
 select a.id into acct from public.accounts a where a.owner_user_id = auth.uid();
 if auth.uid() is null or acct is null then raise exception 'not the owner of an account' using errcode = '42501'; end if;
 return (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'kind', o.kind, 'state', o.state, 'store_name', o.store_name,
   'business_id', o.business_id, 'amount_cents', o.amount_cents, 'currency', o.currency, 'payment_deadline', o.payment_deadline,
   'error_code', o.last_error_code, 'created_at', o.created_at) order by o.created_at desc), '[]'::jsonb)
  from (select * from public.store_operations x where x.account_id = acct order by x.created_at desc limit 20) o);
end $function$

CREATE OR REPLACE FUNCTION public.provision_paid_registration(p_operation uuid, p_owner_user uuid, p_sub jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 t public.store_transfers%rowtype; v_transfer boolean := false;
 o public.checkout_operations%rowtype;
 d public.registration_drafts%rowtype;
 v_account uuid; v_business uuid; v_subscription uuid;
begin
 select * into o from public.checkout_operations x where x.id = p_operation for update;
 if not found then return jsonb_build_object('outcome','unknown_operation'); end if;
 if o.status = 'provisioned' then
  return jsonb_build_object('outcome','already_provisioned','account_id',o.account_id,'business_id',o.business_id);
 end if;
 if o.status not in ('paid','provisioning') then return jsonb_build_object('outcome','not_paid'); end if;
 if o.stripe_customer_id is distinct from p_sub->>'customer_id' or o.stripe_subscription_id is distinct from p_sub->>'subscription_id' then
  return jsonb_build_object('outcome','mapping_mismatch');
 end if;
 if not exists (select 1 from auth.users u where u.id = p_owner_user) then
  return jsonb_build_object('outcome','owner_missing'); end if;
 if exists (select 1 from public.accounts a where a.owner_user_id = p_owner_user) then
  return jsonb_build_object('outcome','owner_has_account'); end if;
 select * into d from public.registration_drafts x where x.id = o.draft_id for update;
 if d.npi is distinct from o.npi or not public.npi_is_valid(o.npi) then
  return jsonb_build_object('outcome','scope_changed'); end if;
 if not exists (select 1 from public.npi_reservations r where r.operation_id = o.id and r.npi = o.npi and r.status = 'checkout_bound') then
  -- Ruling 3: a transfer buyer's registration consumes the transfer hold and becomes the successor ownership.
  select x.* into t from public.store_transfers x join public.npi_reservations r on r.transfer_id = x.id
   where r.operation_id = o.id and r.npi = o.npi and r.status = 'transfer_held' for update of x;
  if not found then return jsonb_build_object('outcome','reservation_lost'); end if;
  if t.status <> 'buyer_reserved' or t.buyer_email is distinct from lower(d.owner_email)
     or exists (select 1 from public.businesses b where b.pharmacy_id = t.pharmacy_id and b.ownership_ended_at is null) then
   return jsonb_build_object('outcome','transfer_state'); end if;
  v_transfer := true;
 end if;

 insert into public.accounts(name, owner_user_id) values (d.pharmacy_name, p_owner_user) returning id into v_account;
 insert into public.businesses(account_id, npi, ncpdp, pharmacy_name, address, city, state, zip, phone,
   pharmacy_software_system, contact_person, contact_person_last_name, business_email, status, date_of_registration, pharmacy_id)
  values (v_account, o.npi, d.ncpdp, d.pharmacy_name, d.address, d.city, d.state, d.zip, d.phone,
   d.software, d.owner_first_name, d.owner_last_name, d.owner_email, 'active', now(), case when v_transfer then t.pharmacy_id end)
  returning id into v_business;
 -- the owner is the first store's designated admin; ownership itself comes from accounts.owner_user_id
 insert into public.user_businesses(user_id, business_id, role, is_primary) values (p_owner_user, v_business, 'admin', true);
 insert into public.billing_customers(account_id, stripe_customer_id) values (v_account, p_sub->>'customer_id');
 insert into public.subscriptions(account_id, origin, stripe_customer_id, stripe_subscription_id, stripe_checkout_session_id,
   status, raw_status, quantity, stripe_price_id, stripe_subscription_item_id, current_period_start, current_period_end,
   cancel_at_period_end, cancel_at, latest_invoice_id, latest_invoice_status, promotion_code, verified_at, policy_version)
  values (v_account, 'stripe', p_sub->>'customer_id', p_sub->>'subscription_id', o.stripe_checkout_session_id,
   p_sub->>'status', p_sub->>'raw_status', (p_sub->>'quantity')::integer, p_sub->>'price_id', p_sub->>'item_id',
   (p_sub->>'current_period_start')::timestamptz, (p_sub->>'current_period_end')::timestamptz,
   coalesce((p_sub->>'cancel_at_period_end')::boolean, false), (p_sub->>'cancel_at')::timestamptz,
   p_sub->>'latest_invoice_id', p_sub->>'latest_invoice_status', o.promotion_code,
   (p_sub->>'verified_at')::timestamptz, p_sub->>'policy_version')
  returning id into v_subscription;
 update public.npi_reservations r set status = 'consumed' where r.operation_id = o.id and r.status in ('checkout_bound', 'transfer_held');
 if v_transfer then update public.store_transfers x set status = 'completed', buyer_account_id = v_account, buyer_business_id = v_business where x.id = t.id; end if;
 update public.checkout_operations x set status = 'provisioned', owner_user_id = p_owner_user, account_id = v_account,
   business_id = v_business, lease_owner = null, lease_expires_at = null, last_error_code = null where x.id = o.id;
 update public.registration_drafts x set status = 'provisioned' where x.id = o.draft_id;
 return jsonb_build_object('outcome','provisioned','account_id',v_account,'business_id',v_business,'subscription_id',v_subscription);
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  obj record;
BEGIN
  FOR obj IN
    SELECT * FROM pg_event_trigger_ddl_commands() WHERE command_tag = 'CREATE TABLE'
  LOOP
    IF obj.schema_name = 'public' THEN
      EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', obj.object_identity);
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.store_access_state(p_business_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare acct uuid; r jsonb;
begin
 select b.account_id into acct from public.businesses b
  where b.id = p_business_id and b.id in (select public.my_business_ids());
 if acct is null then raise exception 'not a member of business' using errcode='42501'; end if;
 r := public.account_access_state(acct);
 return jsonb_build_object('state', r->'state', 'read_only', r->'read_only', 'origin', r->'origin',
  'policy_version', r->'policy_version', 'is_owner', public.is_owner_of_account(acct));
end $function$

CREATE OR REPLACE FUNCTION public.store_add_activate(p_operation uuid, p_invoice text, p_paid_cents integer, p_currency text, p_quantity integer, p_period_start timestamp with time zone, p_period_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.store_operations%rowtype; a public.accounts%rowtype; v_identity uuid; v_business uuid; v_now timestamptz; t public.store_transfers%rowtype;
begin
 select * into o from public.store_operations x where x.id = p_operation for update;
 if not found or o.kind <> 'store_add' then return jsonb_build_object('outcome', 'unknown_operation'); end if;
 if o.state = 'activated' then return jsonb_build_object('outcome', 'already_activated', 'business_id', o.business_id); end if;
 if o.state <> 'paid_pending_activation' then return jsonb_build_object('outcome', 'not_paid_pending'); end if;
 -- 0070: consent deadline backstop (provider paid time on or before the stored deadline, or an operator resume).
 if o.close_reference is null and (o.provider_paid_at is null or o.provider_paid_at > o.payment_deadline) then
  update public.store_operations x set state = 'attention',
    last_error_code = case when o.provider_paid_at is null then 'paid_time_unverified' else 'paid_after_deadline' end where x.id = o.id;
  return jsonb_build_object('outcome', 'attention', 'code', case when o.provider_paid_at is null then 'paid_time_unverified' else 'paid_after_deadline' end); end if;
 select * into a from public.accounts x where x.id = o.account_id for update;
 if not exists (select 1 from public.provider_invoice_operations m where m.invoice_id = p_invoice and m.operation_id = o.id)
    or o.invoice_id is distinct from p_invoice or p_paid_cents <> o.amount_cents or p_currency <> 'usd' then
  update public.store_operations x set state = 'attention', last_error_code = 'payment_mismatch' where x.id = o.id;
  return jsonb_build_object('outcome', 'attention', 'code', 'payment_mismatch'); end if;
 if p_period_start <> o.period_start or p_period_end <> o.period_end then
  update public.store_operations x set state = 'attention', last_error_code = 'period_changed' where x.id = o.id;
  return jsonb_build_object('outcome', 'attention', 'code', 'period_changed'); end if;
 if p_quantity <> o.target_quantity or public.account_billable_count(o.account_id) + 1 <> o.target_quantity then
  update public.store_operations x set state = 'attention', last_error_code = 'quantity_mismatch' where x.id = o.id;
  return jsonb_build_object('outcome', 'attention', 'code', 'quantity_mismatch'); end if;
 perform pg_advisory_xact_lock(hashtextextended('apbm007a:npi:' || o.npi, 0));
 v_now := public.billing_now(o.account_id);
 if o.reactivation_business_id is not null then
  if not exists (select 1 from public.npi_reservations r where r.store_operation_id = o.id and r.npi = o.npi and r.status = 'op_held')
     or not exists (select 1 from public.store_reactivations r join public.businesses b on b.id = r.business_id where r.business_id = o.reactivation_business_id
       and r.status = 'authorized' and b.status = 'removed' and b.account_id = o.account_id)
     or exists (select 1 from public.businesses b where b.npi = o.npi and b.ownership_ended_at is null) then
   update public.store_operations x set state = 'attention', last_error_code = 'reactivation_state' where x.id = o.id;
   return jsonb_build_object('outcome', 'attention', 'code', 'reactivation_state'); end if;
  -- Decision 9: only now, after payment and quantity reconciliation, the original record and its history return.
  update public.businesses b set status = 'active', ownership_ended_at = null, removal_requested_at = null, removal_effective_at = null,
    reactivated_at = v_now where b.id = o.reactivation_business_id;
  insert into public.user_businesses (user_id, business_id, role, is_primary) values (a.owner_user_id, o.reactivation_business_id, 'admin', false)
   on conflict (user_id, business_id) do update set role = 'admin';
  update public.npi_reservations r set status = 'consumed' where r.store_operation_id = o.id and r.status = 'op_held';
  update public.store_reactivations r set status = 'used' where r.business_id = o.reactivation_business_id and r.status = 'authorized';
  update public.subscriptions s set quantity = p_quantity where s.account_id = o.account_id and s.stripe_subscription_id = o.stripe_subscription_id;
  update public.provider_invoice_operations m set outcome = 'paid', verified_at = now() where m.invoice_id = p_invoice;
  update public.store_operations x set state = 'activated', business_id = o.reactivation_business_id, activated_at = now(),
    lease_owner = null, lease_until = null, last_error_code = null where x.id = o.id;
  return jsonb_build_object('outcome', 'activated', 'business_id', o.reactivation_business_id, 'reactivated', true);
 elsif o.transfer_id is null then
  if not exists (select 1 from public.npi_reservations r where r.store_operation_id = o.id and r.npi = o.npi and r.status = 'op_held') then
   update public.store_operations x set state = 'attention', last_error_code = 'reservation_lost' where x.id = o.id;
   return jsonb_build_object('outcome', 'attention', 'code', 'reservation_lost'); end if;
  if exists (select 1 from public.pharmacy_identities i where i.npi = o.npi) then
   update public.store_operations x set state = 'attention', last_error_code = 'npi_registered' where x.id = o.id;
   return jsonb_build_object('outcome', 'attention', 'code', 'npi_registered'); end if;
  insert into public.pharmacy_identities (npi) values (o.npi) returning id into v_identity;
 else
  select * into t from public.store_transfers x where x.id = o.transfer_id for update;
  if t.status not in ('buyer_reserved', 'attention') or t.buyer_account_id <> o.account_id
     or exists (select 1 from public.businesses b where b.pharmacy_id = t.pharmacy_id and b.ownership_ended_at is null)
     or not exists (select 1 from public.npi_reservations r where r.transfer_id = t.id and r.status = 'transfer_held') then
   update public.store_operations x set state = 'attention', last_error_code = 'transfer_state' where x.id = o.id;
   return jsonb_build_object('outcome', 'attention', 'code', 'transfer_state'); end if;
  v_identity := t.pharmacy_id;
 end if;
 insert into public.businesses (account_id, pharmacy_id, npi, ncpdp, pharmacy_name, status, date_of_registration, ownership_started_at)
  values (o.account_id, v_identity, o.npi, o.ncpdp, o.store_name, 'active', v_now, v_now) returning id into v_business;
 insert into public.user_businesses (user_id, business_id, role, is_primary) values (a.owner_user_id, v_business, 'admin', false);
 update public.npi_reservations r set status = 'consumed' where (r.store_operation_id = o.id and r.status = 'op_held') or (o.transfer_id is not null and r.transfer_id = o.transfer_id and r.status = 'transfer_held');
 if o.transfer_id is not null then update public.store_transfers x set status = 'completed', buyer_business_id = v_business where x.id = o.transfer_id; end if;
 update public.subscriptions s set quantity = p_quantity where s.account_id = o.account_id and s.stripe_subscription_id = o.stripe_subscription_id;
 update public.provider_invoice_operations m set outcome = 'paid', verified_at = now() where m.invoice_id = p_invoice;
 update public.store_operations x set state = 'activated', business_id = v_business, pharmacy_id = v_identity, activated_at = now(),
   lease_owner = null, lease_until = null, last_error_code = null where x.id = o.id;
 return jsonb_build_object('outcome', 'activated', 'business_id', v_business);
end $function$

CREATE OR REPLACE FUNCTION public.store_admin_set(p_business uuid, p_user uuid, p_disposition text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_admin uuid; v_owner uuid;
begin
 if p_disposition not in ('member', 'remove') then return jsonb_build_object('error', 'invalid_disposition'); end if;
 perform 1 from public.businesses b where b.id = p_business for update;
 if not public.store_is_live(p_business) then return jsonb_build_object('error', 'store_not_live'); end if;
 if not exists (select 1 from auth.users u where u.id = p_user and u.email_confirmed_at is not null) then return jsonb_build_object('error', 'user_not_confirmed'); end if;
 select a.owner_user_id into v_owner from public.businesses b join public.accounts a on a.id = b.account_id where b.id = p_business;
 select ub.user_id into v_admin from public.user_businesses ub where ub.business_id = p_business and ub.role = 'admin';
 if v_admin = p_user then return jsonb_build_object('outcome', 'already_admin'); end if;
 if v_admin is not null then
  if p_disposition = 'remove' and v_admin <> v_owner then delete from public.user_businesses ub where ub.business_id = p_business and ub.user_id = v_admin;
  else update public.user_businesses ub set role = 'member' where ub.business_id = p_business and ub.user_id = v_admin; end if;
 end if;
 insert into public.user_businesses (user_id, business_id, role, is_primary) values (p_user, p_business, 'admin', false)
  on conflict (user_id, business_id) do update set role = 'admin';
 update public.store_invitations i set status = 'revoked', revoked_at = now(), status_reason = 'stale_incumbent'
  where i.business_id = p_business and i.status = 'pending' and i.role = 'admin';
 return jsonb_build_object('outcome', 'admin_set', 'previous_admin', v_admin);
end $function$

CREATE OR REPLACE FUNCTION public.store_incremental_cents(p_unit integer, p_start timestamp with time zone, p_end timestamp with time zone, p_at timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s bigint := floor(extract(epoch from p_start)); e bigint := floor(extract(epoch from p_end)); t bigint := floor(extract(epoch from p_at));
begin
 if p_unit is null or p_unit <= 0 or e <= s then raise exception 'invalid billing interval' using errcode = '22023'; end if;
 t := least(greatest(t, s), e);
 return ((p_unit::bigint * (e - t) + (e - s) / 2) / (e - s))::integer;
end $function$

CREATE OR REPLACE FUNCTION public.store_lifecycle_commit(p_operation uuid, p_owner text, p_epoch bigint, p_quantity integer, p_period_start timestamp with time zone, p_period_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.store_operations%rowtype; v_at timestamptz;
begin
 select * into o from public.store_operations x where x.id = p_operation for update;
 if not found or o.kind not in ('store_removal', 'store_removal_undo') then return jsonb_build_object('outcome', 'unknown_operation'); end if;
 if o.state = 'completed' then return jsonb_build_object('outcome', 'already_completed'); end if;
 if o.state <> 'requested' then return jsonb_build_object('outcome', 'not_requested'); end if;
 if o.lease_owner is distinct from p_owner or o.fencing_epoch <> p_epoch or o.lease_until <= now() then return jsonb_build_object('outcome', 'lease_lost'); end if;
 perform 1 from public.accounts a where a.id = o.account_id for update;
 if p_period_start <> o.period_start or p_period_end <> o.period_end then
  update public.store_operations x set state = 'attention', last_error_code = 'period_changed' where x.id = o.id;
  return jsonb_build_object('outcome', 'attention', 'code', 'period_changed'); end if;
 if p_quantity <> o.target_quantity then
  update public.store_operations x set state = 'attention', last_error_code = 'quantity_mismatch' where x.id = o.id;
  return jsonb_build_object('outcome', 'attention', 'code', 'quantity_mismatch'); end if;
 v_at := public.billing_now(o.account_id);
 if o.kind = 'store_removal' then
  update public.businesses b set removal_requested_at = v_at, removal_effective_at = o.period_end where b.id = o.business_id and b.removal_effective_at is null;
 else
  if v_at >= o.period_end then
   update public.store_operations x set state = 'attention', last_error_code = 'cutoff_passed' where x.id = o.id;
   return jsonb_build_object('outcome', 'attention', 'code', 'cutoff_passed'); end if;
  update public.businesses b set removal_requested_at = null, removal_effective_at = null where b.id = o.business_id;
 end if;
 update public.subscriptions s set quantity = p_quantity where s.account_id = o.account_id and s.stripe_subscription_id = o.stripe_subscription_id;
 update public.store_operations x set state = 'completed', lease_owner = null, lease_until = null, last_error_code = null, closed_at = now() where x.id = o.id;
 return jsonb_build_object('outcome', 'completed', 'effective_at', o.period_end, 'billable', public.account_billable_count(o.account_id));
end $function$

CREATE OR REPLACE FUNCTION public.store_lifecycle_request(p_kind text, p_account uuid, p_actor uuid, p_business uuid, p_intent text, p_customer text, p_subscription text, p_item text, p_unit integer, p_quantity integer, p_period_start timestamp with time zone, p_period_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.businesses%rowtype; o public.store_operations%rowtype; v_at timestamptz; v_refusal text; v_billable integer; st jsonb; v_sub public.subscriptions%rowtype;
begin
 if p_kind not in ('store_removal', 'store_removal_undo') then return jsonb_build_object('error', 'invalid_kind'); end if;
 perform 1 from public.accounts a where a.id = p_account for update;
 if not exists (select 1 from public.accounts a where a.id = p_account and a.owner_user_id = p_actor) then return jsonb_build_object('error', 'not_owner'); end if;
 select * into o from public.store_operations x where x.account_id = p_account and x.intent_key = p_intent;
 if found then
  if o.kind = p_kind and o.business_id = p_business then return jsonb_build_object('operation', to_jsonb(o) - 'hosted_invoice_url', 'resumed', true); end if;
  return jsonb_build_object('error', 'intent_conflict');
 end if;
 select * into b from public.businesses x where x.id = p_business and x.account_id = p_account for update;
 if not found or not public.store_is_live(b.id) then return jsonb_build_object('error', 'store_not_found'); end if;
 if exists (select 1 from public.store_transfers t where t.source_business_id = b.id and t.status in ('authorized', 'buyer_reserved', 'attention')) then
  return jsonb_build_object('error', 'transfer_in_progress'); end if;
 st := public.account_access_state(p_account);
 if st->>'state' in ('read_only', 'ended') then return jsonb_build_object('error', 'account_read_only'); end if;
 if exists (select 1 from public.store_operations x where x.account_id = p_account
   and x.state in ('payment_setup','payment_pending','paid_pending_activation','cancel_requested','attention','requested')) then
  return jsonb_build_object('error', 'operation_unresolved'); end if;
 select * into v_sub from public.subscriptions s where s.account_id = p_account and s.origin = 'stripe' and s.status <> 'canceled' order by s.created_at desc limit 1;
 if not found or v_sub.stripe_subscription_id is distinct from p_subscription or v_sub.stripe_customer_id is distinct from p_customer then
  return jsonb_build_object('error', 'billing_binding_mismatch'); end if;
 v_billable := public.account_billable_count(p_account);
 if p_quantity is distinct from v_billable then return jsonb_build_object('error', 'quantity_mismatch'); end if;
 v_at := public.billing_now(p_account);
 if p_period_start > v_at or p_period_end <= v_at then return jsonb_build_object('error', 'period_mismatch'); end if;
 v_refusal := public.store_period_window_refusal(p_unit, p_period_start, p_period_end, v_at);
 if v_refusal is not null then return jsonb_build_object('error', v_refusal); end if;
 if p_kind = 'store_removal' then
  if b.removal_effective_at is not null then return jsonb_build_object('error', 'already_scheduled'); end if;
  if v_billable <= 1 then return jsonb_build_object('error', 'last_store'); end if;
 else
  if b.removal_effective_at is null then return jsonb_build_object('error', 'not_scheduled'); end if;
  if v_at >= b.removal_effective_at then return jsonb_build_object('error', 'cutoff_passed'); end if;
  if b.removal_effective_at <> p_period_end then return jsonb_build_object('error', 'period_mismatch'); end if;
 end if;
 insert into public.store_operations (account_id, kind, state, intent_key, actor_user_id, business_id, stripe_customer_id, stripe_subscription_id,
   stripe_item_id, period_start, period_end, target_quantity)
 values (p_account, p_kind, 'requested', p_intent, p_actor, b.id, p_customer, p_subscription, p_item, p_period_start, p_period_end,
   case when p_kind = 'store_removal' then v_billable - 1 else v_billable + 1 end)
 returning * into o;
 return jsonb_build_object('operation', to_jsonb(o) - 'hosted_invoice_url', 'resumed', false);
end $function$

CREATE OR REPLACE FUNCTION public.store_operation_claim(p_quote uuid, p_actor uuid, p_intent text, p_terms_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q public.store_quotes%rowtype; o public.store_operations%rowtype; v_at timestamptz; v_deadline timestamptz; v_refusal text;
begin
 select * into q from public.store_quotes x where x.id = p_quote;
 if not found then return jsonb_build_object('error', 'quote_not_found'); end if;
 perform 1 from public.accounts a where a.id = q.account_id for update;
 if q.actor_user_id is distinct from p_actor or not exists (select 1 from public.accounts a where a.id = q.account_id and a.owner_user_id = p_actor) then
  return jsonb_build_object('error', 'not_owner'); end if;
 select * into o from public.store_operations x where x.account_id = q.account_id and x.intent_key = p_intent;
 if found then
  if o.quote_id = q.id then return jsonb_build_object('operation', to_jsonb(o) - 'hosted_invoice_url', 'resumed', true); end if;
  if o.kind = 'store_add' and o.npi = q.npi and o.store_name = q.store_name and o.state not in ('expired_unpaid','closed_refunded_externally','activated') then
   return jsonb_build_object('operation', to_jsonb(o) - 'hosted_invoice_url', 'resumed', true); end if;
  return jsonb_build_object('error', 'intent_conflict');
 end if;
 if exists (select 1 from public.store_operations x where x.quote_id = q.id) then return jsonb_build_object('error', 'quote_used'); end if;
 v_at := public.billing_now(q.account_id);
 if v_at >= q.expires_at then return jsonb_build_object('error', 'quote_expired'); end if;
 if p_terms_version is distinct from q.terms_version then return jsonb_build_object('error', 'terms_changed'); end if;
 v_refusal := public.account_add_store_refusal(q.account_id);
 if v_refusal is not null then return jsonb_build_object('error', v_refusal); end if;
 if public.account_billable_count(q.account_id) <> q.billable_before then return jsonb_build_object('error', 'quantity_changed'); end if;
 v_refusal := public.store_period_window_refusal(q.additional_unit_cents, q.period_start, q.period_end, v_at);
 if v_refusal is not null then return jsonb_build_object('error', v_refusal); end if;
 if exists (select 1 from public.store_operations x where x.account_id = q.account_id
   and x.state in ('payment_setup','payment_pending','paid_pending_activation','cancel_requested','attention','requested')) then
  return jsonb_build_object('error', 'operation_unresolved'); end if;
 perform pg_advisory_xact_lock(hashtextextended('apbm007a:npi:' || q.npi, 0));
 if q.reactivation_business_id is not null then
  if not exists (select 1 from public.store_reactivations r join public.businesses b on b.id = r.business_id where r.business_id = q.reactivation_business_id
      and r.status = 'authorized' and r.account_id = q.account_id and b.status = 'removed' and b.account_id = q.account_id)
     or exists (select 1 from public.businesses b where b.npi = q.npi and b.ownership_ended_at is null) then
   return jsonb_build_object('error', 'reactivation_not_authorized'); end if;
  if exists (select 1 from public.npi_reservations x where x.npi = q.npi and x.status in ('held','checkout_bound','op_held','transfer_held')) then
   return jsonb_build_object('error', 'npi_held'); end if;
 elsif q.transfer_id is null then
  if exists (select 1 from public.pharmacy_identities i where i.npi = q.npi) or exists (select 1 from public.businesses b where b.npi = q.npi) then
   return jsonb_build_object('error', 'npi_registered'); end if;
  if exists (select 1 from public.npi_reservations x where x.npi = q.npi and x.status in ('held','checkout_bound','op_held','transfer_held')) then
   return jsonb_build_object('error', 'npi_held'); end if;
 else
  if not exists (select 1 from public.store_transfers t where t.id = q.transfer_id and t.buyer_account_id = q.account_id and t.status = 'buyer_reserved'
      and v_at >= t.effective_at and now() < t.hold_expires_at) then return jsonb_build_object('error', 'transfer_not_reserved'); end if;
  if exists (select 1 from public.businesses b where b.npi = q.npi and b.ownership_ended_at is null) then return jsonb_build_object('error', 'npi_registered'); end if;
 end if;
 v_deadline := least(v_at + interval '30 minutes', q.period_end - interval '60 minutes');
 insert into public.store_operations (account_id, kind, state, intent_key, actor_user_id, quote_id, store_name, npi, ncpdp, pharmacy_id, transfer_id,
   amount_cents, currency, consented_at, consent_terms_version, payment_deadline, stripe_customer_id, stripe_subscription_id, stripe_item_id,
   period_start, period_end, target_quantity, reactivation_business_id)
 values (q.account_id, 'store_add', 'payment_setup', p_intent, p_actor, q.id, q.store_name, q.npi, q.ncpdp, q.pharmacy_id, q.transfer_id,
   q.amount_cents, 'usd', v_at, q.terms_version, v_deadline, q.stripe_customer_id, q.stripe_subscription_id, q.stripe_item_id,
   q.period_start, q.period_end, q.billable_after, q.reactivation_business_id)
 returning * into o;
 if q.transfer_id is null then
  insert into public.npi_reservations (npi, store_operation_id, status, expires_at) values (q.npi, o.id, 'op_held', v_deadline);
 end if;   -- a transfer buyer keeps the transfer hold; it is consumed at activation
 return jsonb_build_object('operation', to_jsonb(o) - 'hosted_invoice_url', 'resumed', false);
end $function$

CREATE OR REPLACE FUNCTION public.store_operation_close(p_operation uuid, p_invoice text, p_paid_cents integer, p_refunded_cents integer, p_credited_cents integer, p_currency text, p_proof_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.store_operations%rowtype;
begin
 select * into o from public.store_operations x where x.id = p_operation for update;
 if not found or o.kind <> 'store_add' then return jsonb_build_object('error', 'unknown_operation'); end if;
 if o.state = 'closed_refunded_externally' then return jsonb_build_object('outcome', 'already_closed', 'close_reference', o.close_reference); end if;
 if o.state not in ('paid_pending_activation', 'attention') then return jsonb_build_object('error', 'not_closable', 'state', o.state); end if;
 if o.invoice_id is distinct from p_invoice or p_currency <> 'usd' or p_paid_cents <> o.amount_cents then return jsonb_build_object('error', 'proof_mismatch'); end if;
 if coalesce(p_refunded_cents, 0) + coalesce(p_credited_cents, 0) < p_paid_cents then return jsonb_build_object('error', 'partial_proof'); end if;
 if p_proof_ref is null or length(btrim(p_proof_ref)) < 3 then return jsonb_build_object('error', 'proof_reference_required'); end if;
 update public.store_operations x set state = 'closed_refunded_externally', closed_at = now(), close_reference = p_proof_ref, lease_owner = null, lease_until = null where x.id = o.id;
 update public.npi_reservations r set status = 'released' where r.store_operation_id = o.id and r.status = 'op_held';
 update public.provider_invoice_operations m set outcome = 'paid', verified_at = now() where m.invoice_id = p_invoice;
 return jsonb_build_object('outcome', 'closed', 'close_reference', p_proof_ref);
end $function$

CREATE OR REPLACE FUNCTION public.store_operation_map_invoice(p_operation uuid, p_owner text, p_epoch bigint, p_invoice text, p_customer text, p_cents integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.store_operations%rowtype;
begin
 select * into o from public.store_operations x where x.id = p_operation for update;
 if o.lease_owner is distinct from p_owner or o.fencing_epoch <> p_epoch or o.lease_until <= now() then return 'lease_lost'; end if;
 if o.invoice_id is not null and o.invoice_id <> p_invoice then return 'already_mapped_other'; end if;
 if p_cents <> o.amount_cents or p_customer <> o.stripe_customer_id then return 'binding_mismatch'; end if;
 insert into public.provider_invoice_operations (invoice_id, operation_id, artifact_kind, stripe_customer_id, expected_cents, currency)
  values (p_invoice, p_operation, 'store_add_invoice', p_customer, p_cents, 'usd') on conflict (invoice_id) do nothing;
 if not exists (select 1 from public.provider_invoice_operations m where m.invoice_id = p_invoice and m.operation_id = p_operation) then return 'mapped_to_other_operation'; end if;
 update public.store_operations x set invoice_id = p_invoice where x.id = p_operation;
 return 'mapped';
end $function$

CREATE OR REPLACE FUNCTION public.store_operation_payment_observed(p_operation uuid, p_owner text, p_epoch bigint, p_invoice text, p_paid_cents integer, p_currency text, p_paid_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.store_operations%rowtype; v_to text; v_code text;
begin
 select * into o from public.store_operations x where x.id = p_operation for update;
 if not found or o.kind <> 'store_add' then return 'unknown_operation'; end if;
 if o.lease_owner is distinct from p_owner or o.fencing_epoch <> p_epoch or o.lease_until <= now() then return 'lease_lost'; end if;
 -- Already decided (or resumed by the operator after owner reconfirmation): nothing to re-decide.
 if o.state = 'paid_pending_activation' and (o.provider_paid_at is not null or o.close_reference is not null) then return o.state; end if;
 if o.state not in ('payment_pending', 'cancel_requested', 'paid_pending_activation') then return 'transition_refused'; end if;
 if o.invoice_id is distinct from p_invoice or p_paid_cents is distinct from o.amount_cents or p_currency is distinct from 'usd'
    or not exists (select 1 from public.provider_invoice_operations m where m.invoice_id = p_invoice and m.operation_id = o.id) then
  v_to := 'attention'; v_code := 'payment_mismatch';
 elsif o.state = 'cancel_requested' then v_to := 'attention'; v_code := 'paid_after_abandon';
 elsif p_paid_at is null then v_to := 'attention'; v_code := 'paid_time_unverified';
 elsif p_paid_at > o.payment_deadline then v_to := 'attention'; v_code := 'paid_after_deadline';
 else v_to := 'paid_pending_activation'; v_code := null;
 end if;
 update public.store_operations x set state = v_to, last_error_code = v_code, provider_paid_at = coalesce(p_paid_at, x.provider_paid_at)
  where x.id = o.id;
 return v_to;
end $function$

CREATE OR REPLACE FUNCTION public.store_operation_resume(p_operation uuid, p_paid_cents integer, p_reconfirmation_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.store_operations%rowtype;
begin
 select * into o from public.store_operations x where x.id = p_operation for update;
 if not found or o.kind <> 'store_add' then return jsonb_build_object('error', 'unknown_operation'); end if;
 if o.state <> 'attention' then return jsonb_build_object('error', 'not_in_attention', 'state', o.state); end if;
 if p_paid_cents <> o.amount_cents then return jsonb_build_object('error', 'not_paid_in_full'); end if;
 if p_reconfirmation_ref is null or length(btrim(p_reconfirmation_ref)) < 3 then return jsonb_build_object('error', 'reconfirmation_required'); end if;
 if not exists (select 1 from public.npi_reservations r where r.store_operation_id = o.id and r.status = 'op_held') and o.transfer_id is null then
  return jsonb_build_object('error', 'reservation_lost'); end if;
 update public.store_operations x set state = 'paid_pending_activation', last_error_code = null, close_reference = p_reconfirmation_ref where x.id = o.id;
 return jsonb_build_object('outcome', 'resumed');
end $function$

CREATE OR REPLACE FUNCTION public.store_operation_transition(p_operation uuid, p_owner text, p_epoch bigint, p_to text, p_error text, p_invoice text, p_hosted_url text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.store_operations%rowtype;
begin
 select * into o from public.store_operations x where x.id = p_operation for update;
 if not found then return 'unknown_operation'; end if;
 if o.lease_owner is distinct from p_owner or o.fencing_epoch <> p_epoch or o.lease_until <= now() then return 'lease_lost'; end if;
 if not ((o.state, p_to) in (('payment_setup','payment_pending'), ('payment_setup','attention'), ('payment_setup','expired_unpaid'),
   ('payment_pending','attention'), ('payment_pending','expired_unpaid'), ('payment_pending','payment_pending'),
   ('cancel_requested','expired_unpaid'), ('cancel_requested','attention'), ('cancel_requested','paid_pending_activation'),
   ('paid_pending_activation','attention'), ('payment_setup','payment_setup'))) then
  return 'transition_refused'; end if;
 if p_to = 'paid_pending_activation' and o.state = 'cancel_requested' then p_to := 'attention'; p_error := coalesce(p_error, 'paid_after_abandon'); end if;
 update public.store_operations x set state = p_to, last_error_code = p_error,
   invoice_id = coalesce(x.invoice_id, p_invoice), hosted_invoice_url = coalesce(p_hosted_url, x.hosted_invoice_url),
   closed_at = case when p_to = 'expired_unpaid' then now() else x.closed_at end
  where x.id = p_operation;
 if p_to = 'expired_unpaid' then
  update public.npi_reservations r set status = 'released' where r.store_operation_id = p_operation and r.status = 'op_held';
 end if;
 return p_to;
end $function$

CREATE OR REPLACE FUNCTION public.store_quote_create(p_account uuid, p_actor uuid, p_store_name text, p_npi text, p_ncpdp text, p_customer text, p_subscription text, p_item text, p_price text, p_unit integer, p_quantity integer, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_terms_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.accounts%rowtype; v_at timestamptz; v_amount integer; v_refusal text; v_billable integer; q public.store_quotes%rowtype;
        v_identity uuid; v_sub public.subscriptions%rowtype; t public.store_transfers%rowtype; v_react uuid;
begin
 select * into a from public.accounts x where x.id = p_account;
 if not found or a.owner_user_id is distinct from p_actor then return jsonb_build_object('error', 'not_owner'); end if;
 if not public.npi_is_valid(p_npi) then return jsonb_build_object('error', 'invalid_npi'); end if;
 if p_ncpdp is not null and p_ncpdp !~ '^[0-9]{7}$' then return jsonb_build_object('error', 'invalid_ncpdp'); end if;
 v_refusal := public.account_add_store_refusal(p_account);
 if v_refusal is not null then return jsonb_build_object('error', v_refusal); end if;
 if exists (select 1 from public.store_operations o where o.account_id = p_account
   and o.state in ('payment_setup','payment_pending','paid_pending_activation','cancel_requested','attention','requested')) then
  return jsonb_build_object('error', 'operation_unresolved'); end if;
 select * into v_sub from public.subscriptions s where s.account_id = p_account and s.origin = 'stripe' and s.status <> 'canceled' order by s.created_at desc limit 1;
 if not found or v_sub.stripe_subscription_id is distinct from p_subscription or v_sub.stripe_customer_id is distinct from p_customer then
  return jsonb_build_object('error', 'billing_binding_mismatch'); end if;
 v_billable := public.account_billable_count(p_account);
 if p_quantity is distinct from v_billable then return jsonb_build_object('error', 'quantity_mismatch'); end if;
 v_at := public.billing_now(p_account);
 select i.id into v_identity from public.pharmacy_identities i where i.npi = p_npi;
 if v_identity is not null then
  if exists (select 1 from public.businesses b where b.pharmacy_id = v_identity and b.ownership_ended_at is null) then
   if exists (select 1 from public.store_transfers x where x.pharmacy_id = v_identity and x.buyer_account_id = p_account and x.status = 'authorized') then
    return jsonb_build_object('error', 'transfer_not_effective'); end if;
   return jsonb_build_object('error', 'npi_registered'); end if;
  select * into t from public.store_transfers x where x.pharmacy_id = v_identity and x.buyer_account_id = p_account and x.status = 'buyer_reserved';
  if found then
   if v_at < t.effective_at then return jsonb_build_object('error', 'transfer_not_effective'); end if;
   if now() >= t.hold_expires_at then return jsonb_build_object('error', 'transfer_hold_expired'); end if;
  else
   -- Director decision 9: the SAME account re-adds its own removed store (operator-authorized) and gets the original record back.
   select b.id into v_react from public.store_reactivations r join public.businesses b on b.id = r.business_id
    where b.pharmacy_id = v_identity and b.account_id = p_account and b.status = 'removed' and r.account_id = p_account and r.status = 'authorized';
   if v_react is null then return jsonb_build_object('error', 'npi_previously_registered'); end if;
   if exists (select 1 from public.npi_reservations x where x.npi = p_npi and x.status in ('held','checkout_bound','op_held','transfer_held')) then
    return jsonb_build_object('error', 'npi_held'); end if;
  end if;
 elsif exists (select 1 from public.npi_reservations x where x.npi = p_npi and x.status in ('held','checkout_bound','op_held','transfer_held')) then
  return jsonb_build_object('error', 'npi_held');
 end if;
 if p_period_start > v_at or p_period_end <= v_at then return jsonb_build_object('error', 'period_mismatch'); end if;
 v_refusal := public.store_period_window_refusal(p_unit, p_period_start, p_period_end, v_at);
 if v_refusal is not null then return jsonb_build_object('error', v_refusal); end if;
 v_amount := public.store_incremental_cents(p_unit, p_period_start, p_period_end, v_at);
 insert into public.store_quotes (account_id, actor_user_id, store_name, npi, ncpdp, pharmacy_id, transfer_id, stripe_customer_id, stripe_subscription_id, stripe_item_id,
   stripe_price_id, currency, additional_unit_cents, period_start, period_end, computed_at, amount_cents, billable_before, billable_after,
   next_renewal_cents, discount_explanation, terms_version, expires_at, reactivation_business_id)
 values (p_account, p_actor, btrim(p_store_name), p_npi, p_ncpdp, v_identity, t.id, p_customer, p_subscription, p_item, p_price, 'usd', p_unit,
   p_period_start, p_period_end, v_at, v_amount, v_billable, v_billable + 1, 9900 + p_unit * v_billable,
   'Charged only for the new store from now until your current period ends. Your existing stores and any first-store discount you already received are unchanged.',
   p_terms_version, v_at + interval '15 minutes', v_react)
 returning * into q;
 return jsonb_build_object('quote', to_jsonb(q));
end $function$

CREATE OR REPLACE FUNCTION public.store_reactivation_authorize(p_business uuid, p_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.businesses%rowtype;
begin
 select * into b from public.businesses x where x.id = p_business for update;
 if not found then return jsonb_build_object('error', 'unknown_store'); end if;
 if b.status <> 'removed' then return jsonb_build_object('error', case when b.status = 'transferred' then 'transferred_store' else 'not_removed' end); end if;
 if exists (select 1 from public.businesses x where x.pharmacy_id = b.pharmacy_id and x.ownership_ended_at is null) then return jsonb_build_object('error', 'npi_active_elsewhere'); end if;
 insert into public.store_reactivations (business_id, account_id, operator_action_ref) values (b.id, b.account_id, p_ref)
  on conflict do nothing;
 return jsonb_build_object('outcome', 'authorized', 'policy', 'paid re-add pending Director decision 9; no access or quantity granted');
end $function$

CREATE OR REPLACE FUNCTION public.store_removal_finalize(p_business uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.businesses%rowtype; v_transfer uuid;
begin
 select * into b from public.businesses x where x.id = p_business for update;
 if not found or b.ownership_ended_at is not null then return 'already_final'; end if;
 if b.removal_effective_at is null or public.billing_now(b.account_id) < b.removal_effective_at then return 'not_due'; end if;
 select t.id into v_transfer from public.store_transfers t where t.source_business_id = b.id and t.status = 'authorized' for update;
 update public.businesses x set ownership_ended_at = b.removal_effective_at, removed_at = now(),
   status = case when v_transfer is null then 'removed' else 'transferred' end,
   transferred_at = case when v_transfer is null then null else b.removal_effective_at end
  where x.id = b.id;
 delete from public.user_businesses ub where ub.business_id = b.id;
 if v_transfer is not null then
  perform pg_advisory_xact_lock(hashtextextended('apbm007a:npi:' || b.npi, 0));
  insert into public.npi_reservations (npi, transfer_id, status, expires_at)
   select b.npi, t.id, 'transfer_held', t.hold_expires_at from public.store_transfers t where t.id = v_transfer;
  update public.store_transfers t set status = 'buyer_reserved', source_ended_at = b.removal_effective_at where t.id = v_transfer;
 end if;
 return case when v_transfer is null then 'removed' else 'transferred' end;
end $function$

CREATE OR REPLACE FUNCTION public.store_transfer_authorize(p_source_business uuid, p_buyer_account uuid, p_buyer_email text, p_effective_at timestamp with time zone, p_hold_hours integer, p_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.businesses%rowtype; t public.store_transfers%rowtype; v_email text := lower(btrim(coalesce(p_buyer_email, ''))); v_account uuid := p_buyer_account;
begin
 if v_account is null then
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('error', 'invalid_buyer'); end if;
  -- an email that already owns an account must use that account (Add Store path)
  select a.id into v_account from public.accounts a join auth.users u on u.id = a.owner_user_id where lower(u.email) = v_email;
  if v_account is not null then return jsonb_build_object('error', 'buyer_has_account', 'buyer_account_id', v_account); end if;
  if exists (select 1 from public.businesses x join public.accounts a on a.id = x.account_id join auth.users u on u.id = a.owner_user_id
      where x.id = p_source_business and lower(u.email) = v_email) then return jsonb_build_object('error', 'invalid_buyer'); end if;
 end if;
 select * into b from public.businesses x where x.id = p_source_business for update;
 if not found or not public.store_is_live(b.id) then return jsonb_build_object('error', 'source_not_live'); end if;
 perform 1 from public.accounts a where a.id = b.account_id for update;
 if p_buyer_account is not null and (not exists (select 1 from public.accounts a where a.id = p_buyer_account) or p_buyer_account = b.account_id) then
  return jsonb_build_object('error', 'invalid_buyer'); end if;
 if b.removal_effective_at is not null then return jsonb_build_object('error', 'removal_already_scheduled'); end if;
 if public.account_billable_count(b.account_id) <= 1 then return jsonb_build_object('error', 'source_last_store'); end if;
 if p_effective_at <= public.billing_now(b.account_id) then return jsonb_build_object('error', 'effective_in_past'); end if;
 if exists (select 1 from public.store_transfers x where x.pharmacy_id = b.pharmacy_id and x.status in ('authorized', 'buyer_reserved', 'attention')) then
  return jsonb_build_object('error', 'transfer_open'); end if;
 if exists (select 1 from public.store_operations x where x.account_id = b.account_id
   and x.state in ('payment_setup','payment_pending','paid_pending_activation','cancel_requested','attention','requested')) then
  return jsonb_build_object('error', 'operation_unresolved'); end if;
 insert into public.store_transfers (pharmacy_id, source_business_id, source_account_id, buyer_account_id, buyer_email, effective_at, hold_expires_at, status, operator_action_ref)
  values (b.pharmacy_id, b.id, b.account_id, p_buyer_account, case when p_buyer_account is null then v_email end, p_effective_at,
   p_effective_at + make_interval(hours => least(greatest(coalesce(p_hold_hours, 48), 1), 168)), 'authorized', p_ref)
  returning * into t;
 update public.businesses x set removal_requested_at = public.billing_now(b.account_id), removal_effective_at = p_effective_at where x.id = b.id;
 return jsonb_build_object('transfer', to_jsonb(t));
end $function$

CREATE OR REPLACE FUNCTION public.store_transfer_authorize(p_source_business uuid, p_buyer_account uuid, p_effective_at timestamp with time zone, p_hold_hours integer, p_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.businesses%rowtype; t public.store_transfers%rowtype;
begin
 select * into b from public.businesses x where x.id = p_source_business for update;
 if not found or not public.store_is_live(b.id) then return jsonb_build_object('error', 'source_not_live'); end if;
 perform 1 from public.accounts a where a.id = b.account_id for update;
 if not exists (select 1 from public.accounts a where a.id = p_buyer_account) or p_buyer_account = b.account_id then return jsonb_build_object('error', 'invalid_buyer'); end if;
 if b.removal_effective_at is not null then return jsonb_build_object('error', 'removal_already_scheduled'); end if;
 if public.account_billable_count(b.account_id) <= 1 then return jsonb_build_object('error', 'source_last_store'); end if;
 if p_effective_at <= public.billing_now(b.account_id) then return jsonb_build_object('error', 'effective_in_past'); end if;
 if exists (select 1 from public.store_transfers x where x.pharmacy_id = b.pharmacy_id and x.status in ('authorized', 'buyer_reserved', 'attention')) then
  return jsonb_build_object('error', 'transfer_open'); end if;
 if exists (select 1 from public.store_operations x where x.account_id = b.account_id
   and x.state in ('payment_setup','payment_pending','paid_pending_activation','cancel_requested','attention','requested')) then
  return jsonb_build_object('error', 'operation_unresolved'); end if;
 insert into public.store_transfers (pharmacy_id, source_business_id, source_account_id, buyer_account_id, effective_at, hold_expires_at, status, operator_action_ref)
  values (b.pharmacy_id, b.id, b.account_id, p_buyer_account, p_effective_at, p_effective_at + make_interval(hours => least(greatest(coalesce(p_hold_hours, 48), 1), 168)), 'authorized', p_ref)
  returning * into t;
 update public.businesses x set removal_requested_at = public.billing_now(b.account_id), removal_effective_at = p_effective_at where x.id = b.id;
 return jsonb_build_object('transfer', to_jsonb(t));
end $function$

CREATE OR REPLACE FUNCTION public.store_transfer_cancel(p_transfer uuid, p_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.store_transfers%rowtype;
begin
 select * into t from public.store_transfers x where x.id = p_transfer for update;
 if not found then return jsonb_build_object('error', 'unknown_transfer'); end if;
 if t.status <> 'authorized' then return jsonb_build_object('error', 'not_cancellable', 'status', t.status); end if;
 if public.billing_now(t.source_account_id) >= t.effective_at then return jsonb_build_object('error', 'effective_time_passed'); end if;
 update public.businesses b set removal_requested_at = null, removal_effective_at = null where b.id = t.source_business_id and b.ownership_ended_at is null;
 update public.store_transfers x set status = 'canceled', operator_action_ref = coalesce(p_ref, x.operator_action_ref) where x.id = t.id;
 return jsonb_build_object('transfer_id', t.id, 'status', 'canceled');
end $function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
